package com.bank.sequence.model;

// A desk identified by an integer desk code.
public class DeskNode {
    private final int code;
    private DeskNode left;
    private DeskNode right;

    public DeskNode(int code) { this.code = code; }
    public int getCode() { return code; }
    public DeskNode getLeft() { return left; }
    public DeskNode getRight() { return right; }
    public void setLeft(DeskNode left) { this.left = left; }
    public void setRight(DeskNode right) { this.right = right; }
    public boolean isLeaf() { return left == null && right == null; }
}
