package com.bank.sequence.service;

import com.bank.sequence.model.DeskNode;
import java.util.Arrays;
import java.util.logging.Logger;

// Checks whether a root-to-leaf desk chain exactly matches a mandated sequence.
public class SequencePathService {
    private static final Logger log = Logger.getLogger(SequencePathService.class.getName());

    public boolean hasMandatedPath(DeskNode root, int[] sequence) {
        log.info(() -> "Checking mandated sequence " + Arrays.toString(sequence));
        return dfs(root, sequence, 0);
    }

    private boolean dfs(DeskNode node, int[] seq, int index) {
        // Reject null, overrun, or mismatch at the current position.
        if (node == null || index >= seq.length || node.getCode() != seq[index]) {
            return false;
        }
        log.fine(() -> "Matched code " + node.getCode() + " at index " + index);
        // Success only at a leaf that consumes the whole sequence.
        if (node.isLeaf() && index == seq.length - 1) {
            log.info(() -> "Mandated path satisfied at desk code " + node.getCode());
            return true;
        }
        // Any single matching child path is enough.
        return dfs(node.getLeft(), seq, index + 1)
                || dfs(node.getRight(), seq, index + 1);
    }
}
