package com.bank.sequence;

import com.bank.sequence.model.DeskNode;
import com.bank.sequence.service.SequencePathService;
import java.util.logging.Logger;

public class SequencePathApplication {
    private static final Logger log = Logger.getLogger(SequencePathApplication.class.getName());

    public static void main(String[] args) {
        // Desk tree for Rajesh's high-value payment.
        //   root 10 ; left 20 -> leaf 40 ; right 30
        DeskNode root = new DeskNode(10);
        DeskNode left = new DeskNode(20);
        DeskNode right = new DeskNode(30);
        DeskNode leaf = new DeskNode(40);
        root.setLeft(left);
        root.setRight(right);
        left.setLeft(leaf);

        SequencePathService service = new SequencePathService();

        // Exact matching chain 10-20-40
        log.info("Rajesh SAV2001 sequence {10,20,40}: "
                + service.hasMandatedPath(root, new int[]{10, 20, 40}));

        // Prefix only 10-20 is NOT a leaf chain → rejected
        log.info("Rajesh SAV2001 sequence {10,20}: "
                + service.hasMandatedPath(root, new int[]{10, 20}));
    }
}
